import{_ as a,a0 as l,w as d,s as r,I as e,x as t,a1 as i,A as n,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 sudo 运行的命令中防止使用参数 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 sudo 运行的命令中防止使用参数 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 sudo 运行的命令中防止使用参数 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 sudo 运行的命令中防止使用参数 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20220915 How To Prevent Command Arguments With Sudo In Linux","title":"如何在 sudo 运行的命令中防止使用参数","tag":"202210","desc":""},"relativePath":"202210/20220915 How To Prevent Command Arguments With Sudo In Linux.md","filePath":"[post].md"}'),u={name:"202210/20220915 How To Prevent Command Arguments With Sudo In Linux.md"};function h(g,s,m,k,b,c){const o=l("Link");return d(),r("div",null,[s[24]||(s[24]=e("h1",{id:"如何在-sudo-运行的命令中防止使用参数",tabindex:"-1"},[t("如何在 sudo 运行的命令中防止使用参数 "),e("a",{class:"header-anchor",href:"#如何在-sudo-运行的命令中防止使用参数","aria-label":"Permalink to “如何在 sudo 运行的命令中防止使用参数”"},"​")],-1)),s[25]||(s[25]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202210/04/224059k9jl5kzhlhw5d98j.jpg",alt:""})],-1)),s[26]||(s[26]=e("blockquote",null,[e("p",null,[t("允许用户使用 "),e("code",null,"sudo"),t(" 运行命令，但不带命令行参数。")])],-1)),e("p",null,[s[1]||(s[1]=t("在之前的文章，我们学习了如何 ",-1)),i(o,{href:"https://ostechnix.com/run-programs-in-a-directory-via-sudo/"},{default:n(()=>[...s[0]||(s[0]=[t("通过 sudo 以 root 身份运行目录中的命令",-1)])]),_:1}),s[2]||(s[2]=t("。在这篇指南中，我们将学习如何在 Linux 中 ",-1)),s[3]||(s[3]=e("strong",null,"防止 sudo 运行的命令使用参数",-1)),s[4]||(s[4]=t("。即我们允许一个用户使用 ",-1)),s[5]||(s[5]=e("code",null,"sudo",-1)),s[6]||(s[6]=t(" 运行特权级命令，但是 ",-1)),s[7]||(s[7]=e("strong",null,"不带命令行参数",-1)),s[8]||(s[8]=t("。",-1))]),s[27]||(s[27]=p('<h3 id="背景介绍" tabindex="-1">背景介绍 <a class="header-anchor" href="#背景介绍" aria-label="Permalink to “背景介绍”">​</a></h3><p>你已经知道了，每个命令执行一个特定操作有不同的选项。让我们以 <code>ls</code> 命令为例。</p><p><code>ls</code> 命令会罗列文件夹中的内容，对吗？没错。<code>ls</code> 命令附带了一些命令行选项和标志。例如，你可以用 <code>ls</code> 命令的 <code>-a</code> 标志罗列文件夹中的所有内容（包括隐藏文件）。</p><p>在这份简要指南中，我们将明白如何允许用户通过 <code>sudo</code> 运行 <code>ls</code> 命令，但是不能使用命令行选项或者标志。我讲清楚了吗？接下来让我来展示一下如何做到这点。</p><h3 id="防止使用-sudo-参数" tabindex="-1">防止使用 sudo 参数 <a class="header-anchor" href="#防止使用-sudo-参数" aria-label="Permalink to “防止使用 sudo 参数”">​</a></h3><p>以 <code>root</code> 用户身份编辑 <code>/etc/sudoers</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@Almalinux8CT ~]# visudo</span></span></code></pre></div><p>添加下面一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>user1   ALL=(root)      /usr/bin/ls &quot;&quot;</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/09/Deny-Command-Arguments-With-Sudo.png" alt="Deny Command Arguments With Sudo"></p><p>要注意这里 <code>ls</code> 之后的 <strong>双引号</strong>。双引号会屏蔽用户在给定命令之后输入的参数（比如 <code>ls</code> 命令）。在上面的命令中，<code>user1</code> 能够以 <code>root</code> 身份运行 <code>ls</code> 命令，但是不能使用 <code>ls</code> 命令的选项以及标志。你可以选择其他的指令进行尝试。保存该文件并关闭。</p><p>现在，以 <code>user1</code> 的身份登录系统，并尝试以管理员身份运行 <code>ls</code> 命令，不要添加任何选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[user1@Almalinux8CT ~]$ sudo -u root ls -a</span></span></code></pre></div><p>或许你会遇到下面的报错：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Sorry, user user1 is not allowed to execute &#39;/bin/ls -a&#39; as root on Almalinux8CT.</span></span></code></pre></div><p>不过你可以不添加参数来运行 <code>ls</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[user1@Almalinux8CT ~]$ sudo -u root ls</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/09/Prevent-Command-Arguments-With-Sudo.png" alt="Prevent Command Arguments With Sudo"></p><h3 id="防止所有用户使用命令参数" tabindex="-1">防止所有用户使用命令参数 <a class="header-anchor" href="#防止所有用户使用命令参数" aria-label="Permalink to “防止所有用户使用命令参数”">​</a></h3><p>上述例子像你展示了如何阻止用户以管理员身份运行带有参数的命令。你是否想要对所有用户应用该规则呢？很简单！只需要在 <code>/etc/sudoers</code> 文件中添加一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ALL   ALL=(root)      /usr/bin/ls &quot;&quot;</span></span></code></pre></div><p>现在，系统中的所有用户都可以运行不带参数的 <code>ls</code> 命令。</p><p>想要恢复默认设置，只需要删除最后的双引号，或者删除整行。</p><p>查看帮助手册，了解更多。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man sudoers</span></span></code></pre></div><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>在这份指南中，我们学习了如何允许用户以管理员身份运行命令，但是不能添加任何命令参数。这样可以限制用户误用一些命令行参数。</p><hr>',28)),e("p",null,[s[10]||(s[10]=t("via: ",-1)),i(o,{href:"https://ostechnix.com/prevent-command-arguments-with-sudo/"},{default:n(()=>[...s[9]||(s[9]=[t("https://ostechnix.com/prevent-command-arguments-with-sudo/",-1)])]),_:1})]),e("p",null,[s[15]||(s[15]=t("作者：",-1)),i(o,{href:"https://ostechnix.com/author/sk/"},{default:n(()=>[...s[11]||(s[11]=[t("sk",-1)])]),_:1}),s[16]||(s[16]=t(" 选题：",-1)),i(o,{href:"https://github.com/lkxed"},{default:n(()=>[...s[12]||(s[12]=[t("lkxed",-1)])]),_:1}),s[17]||(s[17]=t(" 译者：",-1)),i(o,{href:"https://github.com/Donkey-Hao"},{default:n(()=>[...s[13]||(s[13]=[t("Donkey-Hao",-1)])]),_:1}),s[18]||(s[18]=t(" 校对：",-1)),i(o,{href:"https://github.com/wxy"},{default:n(()=>[...s[14]||(s[14]=[t("wxy",-1)])]),_:1})]),e("p",null,[s[21]||(s[21]=t("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[19]||(s[19]=[t("LCTT",-1)])]),_:1}),s[22]||(s[22]=t(" 原创编译，",-1)),i(o,{href:"https://linux.cn/"},{default:n(()=>[...s[20]||(s[20]=[t("Linux中国",-1)])]),_:1}),s[23]||(s[23]=t(" 荣誉推出",-1))])])}const T=a(u,[["render",h]]);export{C as __pageData,T as default};
